def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
db=None, imp_user=None, dehydration_hooks=None,
hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Check for valid mode
    if mode not in ("READ", "WRITE"):
        raise ValueError("Invalid mode '{}'".format(mode))
    # Check for valid bookmarks
    if not isinstance(bookmarks, (list, tuple, set)):
        raise TypeError("bookmarks is not iterable")
    for bookmark in bookmarks:
        if not isinstance(bookmark, str):
            raise TypeError("bookmarks must be an iterable of strings")
    # Check for valid metadata
    if not isinstance(metadata, dict):
        raise TypeError("metadata is not a dictionary")
    # Check for valid timeout
    if not timeout is None and not isinstance(timeout, (int, float)):
        raise TypeError("timeout is not a valid number")
    # Check for valid db name
    if not db is None and not isinstance(db, str):
        raise TypeError("db is not a valid string")
    # Check for valid impersonated user
    if not imp_user is None and not isinstance(imp_user, str):
        raise TypeError("imp_user is not a valid string")
    # Check for valid dehydration hooks
    if not dehydration_hooks is None and not isinstance(dehydration_hooks, dict):
        raise TypeError("dehydration_hooks is not a dictionary")
    for key in dehydration_hooks.keys():
        if not isinstance(key, type):
            raise TypeError("dehydration_hooks keys must be types")
    for value in dehydration_hooks.values():
        if not callable(value):
            raise TypeError("dehydration_hooks values must be functions")
    # Check for valid hydration hooks
    if not hydration_hooks is None and not isinstance(hydration_hooks, (dict, list)):
        raise TypeError("hydration_hooks is not a dictionary or list")
    for index, value in enumerate(hydration_hooks):
        if not isinstance(value, type):
            raise TypeError("hydration_hooks values must be types")
        if not callable(value):
            raise TypeError("hydration_hooks values must be functions")
    # Check for valid handlers
    if not all(callable(handler) for handler in handlers.values()):
        raise TypeError("handlers is not a valid dictionary of handler functions")
    # Return response
    return Response(
        self.packer.pack_message(
            0x71, {"mode": mode, "bookmarks": list(bookmarks), "metadata": metadata, "timeout": timeout, "db": db, "imp_user": imp_user, "dehydration_hooks": dehydration_hooks, "hydration_hooks": hydration_hooks}
        ),
        handlers=handlers,
    )

