def point_type(name, fields, srid_map):
    class DynamicPoint(Point):
        __qualname__ = name
        __name__ = name
        _fields = fields
        _srid_map = srid_map
        def __init__(self, *args, **kwargs):
            super().__init__()
            for i, field in enumerate(self._fields):
                self.__setattr__(field, args[i])
            for k, v in kwargs.items():
                self.__setattr__(k, v)
        def __repr__(self):
            return f"{self.__class__.__name__}({self._fields}, {self._srid_map})"
        def __str__(self):
            return f"{self.__class__.__name__}({self._fields}, {self._srid_map})"
        def __len__(self):
            return len(self._fields)
        def __getitem__(self, item):
            return self.__getattribute__(self._fields[item])
        def __setitem__(self, item, value):
            self.__setattr__(self._fields[item], value)
        def __delitem__(self, item):
            delattr(self, self._fields[item])
        def __copy__(self):
            return Point(self._srid_map)
        def __deepcopy__(self, memo):
            return Point(self._srid_map)
        def __eq__(self, other):
            if not isinstance(other, Point):
                return False
            return self._srid_map == other._srid_map and self._fields == other._fields

        def __hash__(self):
            return hash(self._srid_map)
        def dispose(self):
            del self._srid_map
            del self._fields
        def get_fields(self):
            return self._fields
        def get_srid_map(self):
            return self._srid_map
    return DynamicPoint

