def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(
                message.format(func.__name__),
                category=DeprecationWarning,
                stacklevel=2
            )
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    for option in code.split("\n"):
        if not option:
            continue
        key, val = option.split("=")
        try:
            RRuntime.R.R_setoption(key, val)
        except RRuntimeError:
            warnings.warn(f"Failed to set R option {key} = {val}")

    # If the user has not specified the encoding, we default to UTF-8
    if "encoding" not in code:
        RRuntime.R.R_setoption("encoding", "UTF-8")

    return code

def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, _max_length: int = _get_platform_max_length(), **kwargs: Any) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    # Launch as many partitions as possible concurrently
    partitions = _get_partitions(target_concurrency)
    with multiprocessing.pool.ThreadPool(partitions) as pool:
        results = []
        for i, args in enumerate(varargs):
            pty_cmd = cmd + (args,)
            pty_r, pty_w = tty.openpty()  # Make a pty if on a platform that supports it
            child_pid = os.fork()
            if child_pid == 0:
                # The child
                if color:
                    stty.setwinsize(pty_w)
                # Redirect standard input and output to the pty
                with open(pty_r, "rb", closefd=False) as pty_r_file, open(pty_w, "wb", closefd=False) as pty_w_file:
                    for cmd_arg in pty_cmd:
                        pty_r_file.write(cmd_arg.encode())
                    pty_r_file.close()
                    with tty.error(pty_r, _ignored_errnos, means_pipe_error=True):
                        try:
                            output = pty_w_file.read()
                        except OSError as e:
                            if e.errno == EPIPE:
                                # The read end of the pty was closed. This can happen if the child process exits too early.
                                return
                        finally:
                            pty_w_file.flush()
                            pty_w_file.close()
                    return 0, output
                else:
                    # Execute the command
                    child = subprocess.Popen(pty_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                    output, err = child.communicate()
                    if child.returncode == 0:
                        return 0, output
                    else:
                        return child.returncode, err
            else:
                # The parent
                results.append((pty_w, pty_cmd))

        # Wait for all partitions to finish
        for pty_w, pty_cmd in results:
            with open(pty_w, "rb") as pty_w_file:
                output = pty_w_file.read()
            os.close(pty_w)
            if output:
                yield pty_cmd, output

def _get_platform_max_length() -> int:
    if is_windows():
        # TODO: Figure out how to get the maximum command line length on Windows
        # This is a placeholder value that should work on most modern Windows systems
        return 32767
    else:
        return resource.getrlimit(resource.RLIMIT_CORE)[0] // 10

def _get_partitions(target_concurrency: int) -> int:
    """Get the number of partitions to use based on the target concurrency"""
    if is_windows():
        # Windows has a maximum command line length of 32767 characters
        max_length = _get_platform_max_length()
        return math.ceil(max_length / target_concurrency)
    else:
        # Linux has no limit on command line length
        return target_concurrency

