        return _CacheInfo(self.hits, self.misses, len(self._cache))

    def _ttl_key(self, key: Any) -> Tuple[Any, float]:
        return (key, self._timer() + self._ttl)

    def _infinite_ttl_key(self, key: Any) -> Tuple[Any, Any]:
        return (key, None)

