    def __call__(self, func: Callable[..., T]) -> Callable[..., T]:
        _typed = self._typed
        _maxsize = self._maxsize
        _ttl = self._ttl
        _timer = self._timer
        _cache = self._cache
        _infinite_ttl_cache = self._infinite_ttl_cache
        _hits = self._hits
        _misses = self._misses

