@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.

    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    # Initialize variables
    start = max_level = max_path_level = 0
    level = 0
    path = []

    # Iterate through the call stack to get the function calls
    while True:
        exc = e.__cause__ or e.__context__
        if not exc:
            break
        if level >= start:
            if exc.__class__ == BaseException:
                path.append(exc)
            else:
                path.append(exc.__class__.__name__)
        if level == start:
            level = 0
        else:
            level += 1

    # Build the exception string
    exc_str = ""
    for i, exc in enumerate(path):
        if i == 0:
            exc_str += f"{exc.__class__.__name__}: {exc}"
        elif i < max_path_level:
            exc_str += f"\n  __ Caused by {exc.__class__.__name__}: {exc}"
        else:
            exc_str += f"\n  __ Caused by {exc_str}"

    return exc_str.strip()
