def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Sort the classes by their MRO order
    sorted_classes = sorted(classes, key=lambda x: x.mro())

    # Create a set to hold the minimum set of bases
    minimal_bases = set()

    # Iterate over each class in the sorted list
    for cls in sorted_classes:
        # If the class is not already in the minimal set of bases
        if cls not in minimal_bases:
            # Add it to the set
            minimal_bases.add(cls)

            # Check if the class has any bases that are already in the set
            for base in cls.__bases__:
                if base in minimal_bases:
                    # If it does, remove the class from the set
                    minimal_bases.remove(cls)
                    break

    # Return the ordered list of minimal bases
    return list(minimal_bases)

def minimalBases(classes):
