def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """

    # If there are no arguments, return an empty list
    if not sequence:
        return []

    # If the output argument is not provided, create an empty list
    if output is None:
        output = []

    # If the sequence is not a tuple or a Declaration, wrap it in a tuple
    if not isinstance(sequence, tuple) and not isinstance(sequence, Declaration):
        sequence = (sequence,)

    # If the sequence is a tuple, expand it
    if isinstance(sequence, tuple):
        for item in sequence:
            # If the item is a Declaration, add it directly to the output
            if isinstance(item, Declaration):
                output.append((item,))
            # If the item is a tuple, expand it
            elif isinstance(item, tuple):
                output.extend(item)
            # If the item is an interface or an implements spec, add it directly to the output
            elif isinstance(item, Interface) or isinstance(item, ImplementsSpec):
                output.append((item,))
            else:
                raise TypeError("_normalizeargs() argument must be a sequence of Declarations, tuples, or interfaces")

    return output

