    """Get error indices corresponding to a coordinate.

    Raises:
        ValueError: If the coordinate name is not valid.
        TypeError: If the coordinate name is not a string.
    """
    if not isinstance(coord_name, str):
        raise TypeError("Coordinate name must be a string.")

    if coord_name == 'x':
        return self._x_err_indices
    elif coord_name == 'y':
        return self._y_err_indices
    elif coord_name == 'z':
        return self._z_err_indices
