def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate.

    Parameters:
        coord_name (str): The coordinate name

    Returns:
        list[int]: The error indices
    """
    if coord_name not in self.header:
        raise ValueError("Invalid coordinate name")

    coord_index = list(self.header).index(coord_name)
    error_indices = set()

    for i, value in enumerate(self.values[coord_index]):
        if value in ERROR_INDICES:
            error_indices.add(i)

    return list(error_indices)

