def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for key, value in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field {key} not present in Kubernetes response")
        if isinstance(value, dict):
            last_applied_manifest.setdefault(key, {})
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], value, response[key])
        else:
            last_applied_manifest.setdefault(key, value)
            if key in response:
                last_applied_manifest[key] = response[key]
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema.get("observedFields", []):
        if field not in last_applied_manifest:
            if field in response:
                last_applied_manifest[field] = response[field]
            else:
                raise KeyError(f"Observed field {field} not found in Kubernetes response.")

    for field, observer_subschema in observer_schema.get("observedFields", []).items():
        if field in last_applied_manifest:
            last_applied_manifest[field] = update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_subschema, response[field])

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema.get('properties', {}):
        if field not in last_applied_manifest:
            last_applied_manifest[field] = None
        if field not in response:
            raise KeyError(f"Observed field {field} is not present in the Kubernetes response")
        if isinstance(response[field], dict):
            last_applied_manifest[field] = update_last_applied_manifest_dict_from_resp(last_applied_manifest.get(field, {}),
                                                                                      observer_schema.get('properties', {}).get(field, {}),
                                                                                      response[field])
        else:
            last_applied_manifest[field] = response[field]
    return last_applied_manifest

