            if not resource.observer_schema:
                raise GenerateDefaultObserverSchemaError(
                    f"Failed to generate a default observer schema for resource {resource.metadata.name}"
                )
    return app

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
	"""
	Convert the SQL query to use the out-style parameters instead of
	the in-style parameters.

	*sql* (:class:`str` or :class:`bytes`) is the SQL query.

	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
	contains the set of in-style parameters. It maps each parameter
	(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
	is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
	If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
	*params* must be a :class:`~collections.abc.Sequence`.

	Returns a :class:`tuple` containing:

	-	The formatted SQL query (:class:`str` or :class:`bytes`).

	-	The set of converted out-style parameters (:class:`dict` or
		:class:`list`).
	"""

	if not isinstance(params, (dict, list, tuple)):
		return (sql, params)

	new_params = {} if isinstance(params, dict) else []
	for param, value in params.items():
		if isinstance(param, str):
			param = self.in_style.to_out_style(param)
		new_params[param] = value

	if self.in_style.style == "named":
		params = {key: value for key, value in new_params.items() if key not in self.reserved}
	else:
		params = list(new_params.values())

	return (sql % params, params)

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Step 1: Check if path is a directory
    if not os.path.isdir(path):
        raise ValueError("Path is not a directory: {}".format(path))

    # Step 2: Check for required files and directories
    required_files = [os.path.join(path, "ocfl_layout.json")]
    required_dirs = [os.path.join(path, "ocfl_1.0"), os.path.join(path, "ocfl_objects")]
    for file in required_files:
        if not os.path.exists(file):
            raise FileNotFoundError("Required file not found: {}".format(file))
    for dir in required_dirs:
        if not os.path.exists(dir):
            raise FileNotFoundError("Required directory not found: {}".format(dir))

    # Step 3: Check for reserved names in objects directory
    object_dirs = [os.path.join(path, "ocfl_objects", dir) for dir in os.listdir(os.path.join(path, "ocfl_objects"))]
    for dir in object_dirs:
        for file in os.listdir(dir):
            if file.startswith("."):
                raise ValueError("Reserved name used in objects directory: {}".format(os.path.join(dir, file)))

    # Step 4: Check for valid OCFL object IDs
    for dir in object_dirs:
        object_id = os.path.basename(dir)
        if not re.match(r"[a-zA-Z0-9]{8,} _ [a-zA-Z0-9]{4,}", object_id):
            raise ValueError("Invalid OCFL object ID: {}".format(object_id))

    # Step 5: Check for version directories
    for dir in object_dirs:
        if not os.path.exists(os.path.join(dir, "v1")):
            raise ValueError("Missing v1 directory in object: {}".format(os.path.basename(dir)))

    # Step 6: Check for inventory.json file in each version directory
    for dir in object_dirs:
        if not os.path.exists(os.path.join(dir, "v1", "inventory.json")):
            raise FileNotFoundError("Missing inventory.json file in version directory: {}".format(os.path.basename(dir)))

    # Step 7: Check for invalid characters in file names
    for dir in object_dirs:
        for file in os.listdir(dir):
            if not re.match(r"^[a-zA-Z0-9_]+\.[a-zA-Z0-9]{3}$", file):
                raise ValueError("Invalid character in file name: {}".format(os.path.join(dir, file)))

    # Step 8: Check for duplicate files
    for dir in object_dirs:
        files = os.listdir(dir)
        for file in files:
            if file in files and not os.path.isfile(os.path.join(dir, file)):
                raise ValueError("Duplicate file detected: {}".format(os.path.join(dir, file)))

    return True

