def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    prior.check_inventory_integrity()

    # Check that the prior inventory is an earlier version than the current inventory
    if not self.inventory_date < prior.inventory_date:
        raise InvalidInventoryException("The prior inventory is not an earlier version than the current inventory")

    # Check that all items in the prior inventory are present in the current inventory
    for item in prior.items.values():
        if item not in self.items.values():
            raise InvalidInventoryException(f"Item '{item.name}' is missing from the current inventory")

    # Check that all items in the current inventory were present in the prior inventory
    for item in self.items.values():
        if item not in prior.items.values():
            raise InvalidInventoryException(f"Item '{item.name}' is not present in the prior inventory")

    # Check that all items in the current inventory have the same quantity as in the prior inventory
    for item in self.items.values():
        if item.quantity != prior.items[item.name].quantity:
            raise InvalidInventoryException(f"Item '{item.name}' has a different quantity in the current inventory than in the prior inventory")

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # Check that the prior inventory is a valid inventory object
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Prior inventory is not a valid InventoryValidator object")

    # Check that the current inventory is a valid inventory object
    if not self.is_valid:
        raise ValueError("Current inventory is not valid")

    # Check that the current inventory is not a previous version of the prior inventory
    if prior.version >= self.version:
        raise ValueError("Current inventory cannot be a previous version of the prior inventory")

    # Check that all elements in the prior inventory are present in the current inventory
    for element in prior.elements:
        if element not in self.elements:
            raise ValueError("Current inventory is missing element from prior inventory: " + str(element))

    # Check that all of the current inventory's elements have the same name and version as the prior inventory
    for element in self.elements:
        if element.name != prior.elements[element].name or element.version != prior.elements[element].version:
            raise ValueError("Current inventory has mismatched element version for " + str(element))

    # Check that all of the current inventory's features are present in the prior inventory
    for feature in self.features:
        if feature not in prior.features:
            raise ValueError("Current inventory has feature that is not in prior inventory: " + str(feature))

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")
    # Check that each element in self is present in prior and has the same values
    for element in self:
        prior_element = prior.get_element(element.id)
        if not prior_element:
            raise ValueError("prior inventory is missing element " + element.id)
        for key, value in element.items():
            if prior_element[key] != value:
                raise ValueError("prior inventory has different value for element " + element.id + " key " + key)
    # Check that prior has no elements that are not in self
    for element in prior:
        if not self.get_element(element.id):
            raise ValueError("prior inventory has extra element " + element.id)
    return True

