def _explore_zipfile(zip_path):
    """Get packages' data from zip_path"""
    with ZipFile(zip_path, 'r') as zipf:
        filelist = zipf.namelist()
        basenames = [os.path.basename(f) for f in filelist]
        filedata = {}
        for basename in set(basenames):
            filedata[basename] = {}
            for file in filter(lambda x: os.path.basename(x) == basename, filelist):
                with zipf.open(file, 'r') as f:
                    filedata[basename][file] = f.read()
    return filedata

