        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Implementation of absorption and negative absorption
    # Using the rules outlined in the docstring
    # Returns the updated list of expressions

    new_list = []
