def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def inner_function(func):
        if not hasattr(self, "_handlers"):
            self._handlers = {}
        if hook not in self._handlers:
            self._handlers[hook] = []
        self._handlers[hook].append(func)
        return func
    return inner_function

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(fn):
        self._registry[hook] = fn
        return fn

    if not self._registry:
        self._registry = {}

    if not isinstance(hook, HookType):
        raise TypeError("'hook' argument must be an instance of HookType.")

    if hook in self._registry:
        raise ValueError(f"Hook '{hook}' has already been registered.")

    return decorator

