def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    for command in commands:
        if not isinstance(command, str):
            raise TypeError("Invalid type for command argument: expected str or list of str, got {}".format(type(command)))
        if not isinstance(args, list):
            raise TypeError("Invalid type for args argument: expected list of str, got {}".format(type(args)))
        if cwd and not isinstance(cwd, str):
            raise TypeError("Invalid type for cwd argument: expected str, got {}".format(type(cwd)))
        if not isinstance(verbose, bool):
            raise TypeError("Invalid type for verbose argument: expected bool, got {}".format(type(verbose)))
        if not isinstance(hide_stderr, bool):
            raise TypeError("Invalid type for hide_stderr argument: expected bool, got {}".format(type(hide_stderr)))
        if env and not isinstance(env, dict):
            raise TypeError("Invalid type for env argument: expected dict, got {}".format(type(env)))


        if isinstance(args, dict):
            args.append(command)
            args = sorted(args)
        else:
            args = [command] + args

        if cwd:
            os.chdir(cwd)

        if env:
            env.update(os.environ)

        completed_process = subprocess.run(
            args, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            encoding="utf-8", errors="replace", env=env
        )

        if completed_process.returncode != 0:
            raise subprocess.CalledProcessError(
                completed_process.returncode,
                args,
                completed_process.stdout,
                completed_process.stderr,
            )

        if completed_process.stdout:
            if hide_stderr:
                completed_process.stderr = None
            if verbose:
                print(completed_process.stdout, end="")

        return completed_process.stdout

