def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    for cls in self.subclasses():
        objects = cls.objects(self)
        num_objects += len(objects)
        for obj in objects:
            if not obj.validate(validate_objects, check_digests, show_warnings):
                good_objects += 1

    return {
        "num_objects": num_objects,
        "good_objects": good_objects
    }

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    if len(self.children) > 0:
        for child in self.children:
            if isinstance(child, AbstractElement):
                child_num_objects, child_good_objects = child.validate_hierarchy(validate_objects, check_digests, show_warnings)
                num_objects += child_num_objects
                good_objects += child_good_objects
            else:
                if validate_objects:
                    if not child.validate():
                        if show_warnings:
                            print("WARNING: validation failed for object " + child.id + ".")
                else:
                    good_objects += 1
            if check_digests:
                if not child.check_digest():
                    if show_warnings:
                        print("WARNING: checksum validation failed for object " + child.id + ".")
    return (num_objects, good_objects)

