def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise ValueError("invalid argument type")
    if not re.match(r"^[0-9]+$", version):
        raise ValueError("invalid version format")

    if version.startswith("0"):
       return "0" + str(int(version[1:]) + 1).zfill(len(version) - 1)
    else:
       return str(int(version) + 1)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        # remove trailing letters
        major, minor, patch = version.rpartition('v')[2].split('.')
        major, minor, patch = int(major), int(minor), int(patch)
    except ValueError:
        raise ValueError(f'Invalid version string: {version}')
    if patch < 9:
        return f'v{major}.{minor}.{patch + 1}'
    if minor < 9:
        return f'v{major}.{minor + 1}.0'
    return f'v{major + 1}.0.0'

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.endswith('alpha'):
        return version.replace('alpha', 'beta')
    elif version.endswith('beta'):
        return version.replace('beta', 'rc')
    elif version.endswith('rc'):
        v = int(version.split('rc')[0])
        return f'{v+1} final'
    else:
        v = int(version.split('.')[-1])
        return f'{v+1}.0'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        with open(os.path.join(path, "0=*"), "rb") as f:
            namaste = f.read(65536)
    except FileNotFoundError as e:
        return f"File does not exist at path '{path}'"
    except OSError as e:
        return f"Error reading file at path '{path}': {e}"

    # Look for the signature "ocfl_1.0" in the file
    if not namaste.startswith(b"ocfl_1.0"):
        return "file"

    # Look for the line that contains "type: object" or "type: root"
    for line in namaste.splitlines():
        if line.startswith(b"type: object"):
            return "object"
        elif line.startswith(b"type: root"):
            return "root"

    return "other"

