    namastes = os.listdir(path)
    if not any(f.startswith('0=') for f in namastes):
        return "no Namaste files found"
    for f in namastes:
        if f.startswith('0='):
            info = open(os.path.join(path, f), 'r').read()
            if 'ocfl_version' in info:
