    subparser_namespaces = {}
    for name, subparser in subparsers.items():
        try:
            namespace = subparser.parse_known_args(unparsed_arguments)
        except SystemExit:
            return {}, unparsed_arguments
        subparser_namespaces[name] = namespace

    # Second pass: see if any subparser claimed all arguments
    claimed_arguments = []
    for name, namespace in subparser_namespaces.items():
        if not namespace.unparsed_arguments:
            return {name: namespace}, []
        claimed_arguments.extend(namespace.unparsed_arguments)

    # Third pass: if no subparser claimed all arguments, return the set of all known arguments
    # and the set of remaining arguments.
    known_arguments = set()
    for subparser in subparsers.values():
        known_arguments.update(subparser._option_string_actions.keys())
    remaining_arguments = set(unparsed_arguments) - known_arguments
    return subparser_namespaces, remaining_arguments

