def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        if not isinstance(vertices, list) or len(vertices) == 0:
            raise ValueError("the vertices of the polygon should be a non-empty list")
        for vertex in vertices:
            if not isinstance(vertex, list) or len(vertex) != 3:
                raise ValueError("each vertex of the polygon should be a list of length 3")
        tuples = []
        for i in range(len(vertices)):
            curr = vertices[i]
            next = vertices[(i+1) % len(vertices)]
            prev = vertices[(i-1) % len(vertices)]
            tuples.append((curr, prev, next))
        return tuples
    except Exception as e:
        raise ValueError("invalid input for vertices") from e

def int_to_string(self, number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and padding < 1:
        raise ValueError("padding must be at least 1")
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list) or not all(isinstance(x, str) for x in alphabet):
        raise TypeError("alphabet must be a list of strings")
    if len(alphabet) < 2:
        raise ValueError("alphabet must have at least 2 elements")

    result = ""
    base = len(alphabet)
    while number > 0:
        number, remainder = divmod(number, base)
        result = alphabet[remainder] + result
    if padding is not None:
        result = result.rjust(padding, alphabet[0])
    return result

