def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if len(alphabet) != len(set(alphabet)):
        raise ValueError("Alphabet must not contain any duplicates.")
    if len(string) > len(alphabet):
        raise ValueError("Input string must not be longer than the alphabet.")

    number = 0
    for i, char in enumerate(string):
        try:
            number += alphabet.index(char) * (len(alphabet) ** i)
        except ValueError:
            raise ValueError("Invalid input string character: " + char)

    return number

