def split(s, platform='this'):
    if platform == 'this':
        platform = os.name

    if platform == 'posix':
        pattern = r"(?:[^\s\"']+|[\"'][^\"']*[\"'])+\s*"
    elif platform == 'nt':
        pattern = r"(?:[^\s\"']+|^\"[^\"]*\"|\"(?<=[\"])[^\"]*(?=[\"])|\"[^\"]*\"|\'[^\']*\'|\'(?<=\')[^\']*(?=\')\')+\s*"
    else:
        raise ValueError("Invalid platform specified")

    args = re.findall(pattern, s)
    return [arg.strip('"\'') for arg in args]

