    except ValueError:
        raise ValueError("frequency must start with a number")
    if unit not in {"day", "days", "week", "weeks", "month", "months", "year", "years"}:
        raise ValueError("frequency must end with a valid unit of time")
    if unit in {"day", "days"}:
        return datetime.timedelta(days=number)
    elif unit in {"week", "weeks"}:
        return datetime.timedelta(weeks=number)
    elif unit in {"month", "months"}:
        return datetime.timedelta(days=number * 30)
    elif unit in {"year", "years"}:
        return datetime.timedelta(days=number * 365)

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    time_units = {
        "s": "seconds",
        "m": "minutes",
        "h": "hours",
        "d": "days",
        "w": "weeks",
        "mo": "months",
        "y": "years"
    }

    match = re.search(r"^(\d+)(\w+)$", frequency.lower())
    if not match:
        raise ValueError("Invalid frequency")

    amount = int(match.group(1))
    unit = match.group(2)

    if unit not in time_units:
        raise ValueError("Invalid time unit")

    return datetime.timedelta(**{time_units[unit]: amount})

