def run_command(self, commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    elif not isinstance(commands, list):
        raise TypeError("commands must be a string or a list of strings")
    if not commands:
        raise ValueError("at least one command must be provided")
    for command in commands:
        self._run_command(command, args, cwd, verbose, hide_stderr, env)

def _run_command(self, command, args, cwd, verbose, hide_stderr, env):
    if not self.args:
        self.args = []
    if not self.kwargs:
        self.kwargs = {}
    if cwd:
        self.kwargs["cwd"] = cwd
    if verbose:
        self.kwargs["stdout"] = subprocess.PIPE
        self.kwargs["stderr"] = subprocess.PIPE
        if not hide_stderr:
            self.kwargs["stderr"] = subprocess.PIPE
    if env:
        self.kwargs["env"] = env
    try:
        self.proc = subprocess.Popen(command, *args, **self.kwargs)
    except FileNotFoundError:
        raise
    except subprocess.CalledProcessError as e:
        self.error = e
        self.returncode = e.returncode
    else:
        self.returncode = self.proc.wait()
    finally:
        if self.proc:
            self.proc.stdout.close()
            self.proc.stderr.close()
            self.proc.terminate()
        self.stdout = self.stdout.decode()
        self.stderr = self.stderr.decode()
        self.output = self.stdout + self.stderr

