    for val in values:
        try:
            bm.add(Bookmark.from_raw(val))
        except ValueError as e:
            warnings.warn(f'Failed to parse bookmark value: {val}', SyntaxWarning)
    return bm

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.

    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if bufsize is None:
        return (seq, type(seq))
    else:
        return (
            [type(seq).__name__ + "_bufsize" + str(bufsize)],
            type(seq).__name__,
        )

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if not isinstance(seq, (list, tuple)):
        raise TypeError("seq must be a list or tuple")
    if bufsize is None:
        bufsize = len(seq)
    elif not isinstance(bufsize, int):
        raise TypeError("bufsize must be an integer")
    if bufsize < 0:
        raise ValueError("bufsize must be non-negative")
    seq_type = tuple if isinstance(seq, tuple) else list
    return seq_type(seq), seq_type

