def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        return ([seq], str)
    elif isinstance(seq, bytes):
        return ([seq], bytes)
    elif isinstance(seq, bytearray):
        return ([seq], bytearray)
    elif isinstance(seq, memoryview):
        return ([seq], memoryview)
    elif isinstance(seq, list):
        return ([seq], list)
    elif isinstance(seq, tuple):
        return ([seq], tuple)
    elif isinstance(seq, range):
        return (range(len(seq)), range)
    elif isinstance(seq, itertools.chain):
        return (seq, itertools.chain)
    elif isinstance(seq, collections.Sequence):
        return (list(seq), collections.Sequence)
    else:
        raise TypeError("unknown sequence type")

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, bytes):
        return bytes, bytes
    elif isinstance(seq, bytearray):
        return bytearray, bytes
    else:
        if isinstance(seq, (memoryview, buffer)):
            return bytes, bytes
        else:
            return seq, type(seq)

def scale(self, other=None):

    if other is None:
        return self._scale

    if not isinstance(other, numbers.Number) or other <= 0:
        raise ValueError("Scale must be a positive number.")

    if self._scale is None or self._scale == 0:
        raise LenaValueError("Cannot rescale a graph with unknown or zero scale.")

    self.xscales *= other
    self.yscales *= other
    self.escales *= other
    self._scale *= other

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"{candidate} does not provide {iface.__name__}")

    missing_methods = []
    for name, sig in iface.namesAndSignatures():
        if not hasattr(candidate, name):
            missing_methods.append(name)
            continue
        if not isinstance(getattr(candidate, name), types.MethodType):
            raise zope.interface.Invalid(f"Invalid signature for method {name}: "
                                        f"expected {sig.__name__}, "
                                        f"got {getattr(candidate, name).__name__}")

    missing_attrs = []
    for name, v in iface.namesAndDescriptions():
        if not hasattr(candidate, name):
            missing_attrs.append(name)
            continue
        if not isinstance(getattr(candidate, name), type(v)):
            raise zope.interface.Invalid(f"Invalid type for attribute {name}: "
                                        f"expected {type(v).__name__}, "
                                        f"got {type(getattr(candidate, name)).__name__}")

    if missing_methods or missing_attrs:
        raise zope.interface.Invalid(f"{candidate} is missing the following items: "
                                    f"{', '.join(missing_methods)}; "
                                    f"{', '.join(missing_attrs)}")

    if vtype is not None:
        try:
            validator = zope.interface.getValidator(iface, vtype)
        except KeyError:
            raise zope.interface.Invalid(f"No validator for type {vtype} in {iface}")

        try:
            validator(candidate)
        except zope.interface.Invalid as e:
            raise e

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if not tentative and not iface.providedBy(candidate):
        raise Invalid("Candidate {!r} does not provide the '{}' interface.".format(candidate, iface))

    missing_methods = [
        name
        for name in iface.names(methods=True)
        if not hasattr(candidate, name)
    ]

    invalid_methods = []
    for name in missing_methods:
        try:
            signature = getattr(iface, name).getSignature()
            bound_method = getattr(candidate, name).getBoundSignature()
            if bound_method != signature:
                invalid_methods.append(name)
        except AttributeError:
            pass

    missing_attributes = [
        name
        for name in iface.names(attributes=True)
        if not hasattr(candidate, name)
    ]

    invalid_attributes = []
    for name in missing_attributes:
        try:
            interface_attr = getattr(iface, name)
            candidate_attr = getattr(candidate, name)
            if not isinstance(candidate_attr, interface_attr.field.__class__):
                invalid_attributes.append(name)
        except AttributeError:
            pass

    errors = []
    if missing_methods:
        errors.append("{} method(s) missing: {}.".format(len(missing_methods), ", ".join(sorted(missing_methods))))
    if invalid_methods:
        errors.append("{} method(s) signature does not match: {}.".format(len(invalid_methods), ", ".join(sorted(invalid_methods))))
    if missing_attributes:
        errors.append("{} attribute(s) missing: {}.".format(len(missing_attributes), ", ".join(sorted(missing_attributes))))
    if invalid_attributes:
        errors.append("{} attribute(s) do not match the expected type: {}.".format(len(invalid_attributes), ", ".join(sorted(invalid_attributes))))

    if not errors:
        return True

    if len(errors) == 1:
        raise Invalid(errors[0])
    else:
        raise Invalid("The following errors occurred: {}".format("; ".join(errors)))

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not inspect.isclass(candidate):
        raise ValueError("Candidate is not a class")

    if not inspect.isabstract(iface) and not issubclass(candidate, iface):
        raise ValueError("Candidate is not a subclass of the interface")

    for name, attr in inspect.getmembers(iface):
        if not isinstance(attr, property):

            if name not in candidate.__dict__:
                raise ValueError(f"Candidate is missing attribute {name}")

            if not isinstance(candidate.__dict__[name], property):
                if candidate.__dict__[name] != iface.__dict__[name]:
                    raise ValueError(f"Candidate attribute {name} does not match the interface")

    if not tentative:
        for name, attr in inspect.getmembers(candidate):
            if isinstance(attr, property):
                if getattr(candidate, name) != getattr(iface, name):
                    raise ValueError(f"Candidate property {name} does not match the interface")
    return True

