    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    return isinstance(candidate, iface) or (tentative and hasattr(candidate, 'provides') and iface in candidate.provides)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    mcs = [base.__class__ for base in bases]
    for mc in mcs:
        if issubclass(mc, type):
            return mc
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc is not None:
        # if explicit metaclass is given, use it directly
        return explicit_mc

    # if no explicit metaclass is given, get all metaclasses from bases
    mcs = []
    for base in bases:
        mc = base.__class__
        if mc not in mcs:
            mcs.append(mc)

    # if there is only one metaclass, return it
    if len(mcs) == 1:
        return mcs[0]

    # if there are multiple metaclasses, try to find a common base class
    # that is a metaclass
    for mc in mcs:
        if all(issubclass(mc, other_mc) for other_mc in mcs):
            return mc

    # if there is no common base class that is a metaclass, raise a TypeError
    raise TypeError("metaclass conflict: %s" % ", ".join(
        mc.__name__ for mc in mcs))

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        mc = explicit_mc
    elif any(isinstance(b, type) and issubclass(b, type) for b in bases):
        mc = type
    else:
        mc = type
    return mc

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If any of the bases has a custom metaclass, use it
    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__
    # If there is an explicit __metaclass__, use it
    if explicit_mc is not None:
        return explicit_mc
    # Otherwise, use the default metaclass
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclass = MetaType
    for base in bases:
        base_mc = type(base)
        if metaclass is not base_mc:
            raise TypeError("Incompatible metaclasses: {} and {}".format(metaclass, base_mc))
        metaclass = base_mc
    return metaclass

