def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    text_list = text.split()
    for word in text_list:
        if word.startswith('<') and word.endswith('>'):
            tags.add(word[1:-1])
            if replacer is not None:
                new_word = replacer(word[1:-1])
                text_list[text_list.index(word)] = new_word
    return (tags, ' '.join(text_list))

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    text = text.split()
    for word in text:
        if word[0] == '#':
            tags.add(word[1:])
            if replacer:
                word = replacer(word[1:])
    return (tags, ' '.join(text))

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """

    tags = set()
    pos = 0
    while pos < len(text):
        # Find the start of a tag
        start = text.find('<', pos)
        if start == -1:
            break
        if start > 0 and text[start - 1] == '\\':
            # Escaped '<'
            pos = start + 1
            continue

        # Find the end of the tag
        pos = start + 1
        depth = 1
        while pos < len(text):
            if text[pos] == '<':
                depth += 1
            elif text[pos] == '>':
                depth -= 1
                if depth == 0:
                    break
            pos += 1

        if pos == len(text):
            # Unclosed tag
            break

        tag = text[start:pos]
        if replacer is not None:
            tag = replacer(tag)

        tags.add(tag)

    return tags, text.replace('<', '\\<').replace('>', '\\>')


def generate_ingredient_list(ingredients: List[Tuple[str, str]]) -> str:
    """Generate an ingredient list from a list of ingredients.

    The list of ingredients should be a list of tuples, where each tuple contains the
    ingredient name and its measure.

