def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        xml.sax.parseString(doc)
        is_valid_xml = True
    except xml.sax.SAXParseException:
        is_valid_xml = False
    try:
        signature.verify(public_key)
        is_valid_signature = True
    except xml.dsig.InvalidSignature:
        is_valid_signature = False
    if not is_valid_xml or not is_valid_signature:
        raise ValueError("Invalid XML or signature")
    return is_valid_signature

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Check that the signature is valid
    try:
        signature.verify()
    except VerificationError:
        raise ValueError("Invalid signature")
    # Check that the signature is for the expected document
    if not signature.doc:
        raise ValueError("Signature must be for a FoLiA document")
    if signature.doc != doc:
        raise ValueError("Signature is for a different document")
    # Check that the signature is from the claimed author
    if not signature.author:
        raise ValueError("Signature must have an author")
    author = signature.author
    if not author.id:
        raise ValueError("Signature's author must have an ID")
    if author.id not in doc:
        raise ValueError("Signature's author must be in the document")
    # Check that the signature is valid for the claimed author
    try:
        signature.verify_signature(author, public_key)
    except VerificationError:
        raise ValueError("Invalid signature for the author")

