def _include_groups(self, parser_dict):
    if not isinstance(parser_dict, dict):
        raise TypeError("Invalid argument: parser_dict must be a dict.")
    if "groups" not in parser_dict:
        raise KeyError("Invalid argument: missing 'groups' key in parser_dict.")
    if not isinstance(parser_dict["groups"], list):
        raise TypeError("Invalid argument: parser_dict['groups'] must be a list.")

    for group_dict in parser_dict["groups"]:
        if not isinstance(group_dict, dict):
            raise TypeError("Invalid group dict: must be a dict.")
        if "name" not in group_dict:
            raise KeyError("Invalid group dict: missing 'name' key.")
        if not isinstance(group_dict["name"], str):
            raise TypeError("Invalid group name: must be a string.")
        if "tensors" in group_dict:
            if not isinstance(group_dict["tensors"], list):
                raise TypeError("Invalid tensors list: must be a list.")
            for tensor in group_dict["tensors"]:
                if not isinstance(tensor, Tensor):
                    raise TypeError("Invalid tensor: must be an instance of Tensor.")
                self.include_tensor(tensor, group_dict["name"])
        else:
            raise KeyError(f"Invalid group dict for '{group_dict['name']}': missing 'tensors' key.")

    self._groups = {}
    for group_dict in parser_dict["groups"]:
        self._groups[group_dict["name"]] = {
            "tensors": group_dict["tensors"],
            "include": group_dict.get("include", []),
            "exclude": group_dict.get("exclude", []),
        }

def include_tensor(self, tensor, group_name):
    """Adds a tensor to the group with the given name."""
    if not isinstance(tensor, Tensor):
        raise TypeError("Invalid argument: tensor must be an instance of Tensor.")
    if group_name not in self._groups:
        raise KeyError(f"Invalid group name: '{group_name}' does not exist.")
    group = self._groups[group_name]
    if tensor in group["tensors"]:
        return
    group["tensors"] += [tensor]
    self._update_edges(group_name)

def _update_edges(self, group_name):
    """Updates the edges of the group with the given name."""
    group = self._groups[group_name]
    for include in group["include"]:
        include_group = self._groups[include]
        for tensor in include_group["tensors"]:
            if tensor not in group["tensors"]:
                group["tensors"] += [tensor]
    for exclude in group["exclude"]:
        exclude_group = self._groups[exclude]
        for tensor in exclude_group["tensors"]:
            if tensor in group["tensors"]:
                group["tensors"] = [
                    t for t in group["tensors"] if t is not tensor
                ]

