def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): The dictionary to be processed
    """

    for key, value in parser_dict.items():
        if key.startswith('include'):
            parent = None
            child = None
            for char in key:
                if char.isupper():
                    parent = parent or ''
                    parent += char
                else:
                    child = child or ''
                    child += char
            if parent and child:
                # Create a group
                group = Group(self, parent)
                self._groups[parent] = group

                # Include the child in the group
                if not child in self._groups.keys():
                    self._groups.put(Group(child), self, parent)

    # Process remaining elements
    for key, value in parser_dict.items():
        if not key.startswith('include'):
            self._include_groups(value)

