    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}
    for key, value in args.items():
        if key in self.control_args_keys:
            # Control arguments
            control_args[key] = value
        elif key in self.nested_args_keys:
            # Nested arguments
            nested_args[key] = value
        elif key in self.custom_args_keys:
            # Custom arguments
