    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    for key, value in extra_vars.items():
        if key in vars_dict and vars_dict[key] != value:
            raise ValueError("Conflicting values for variable '{}': '{}' and '{}'".format(key, vars_dict[key], value))
        vars_dict[key] = value
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    for var in extra_vars:
        if var not in vars_dict:
            vars_dict[var] = extra_vars[var]

    return vars_dict
