def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    for key, value in extra_vars.items():
        if key in vars_dict and isinstance(vars_dict[key], list):
            vars_dict[key].extend(value)
        else:
            vars_dict[key] = value

    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for arg in values_dict:
        if arg.arg_type == bool:
            values_dict[arg] = bool(values_dict[arg])
        elif arg.arg_type == int:
            values_dict[arg] = int(values_dict[arg])
        elif arg.arg_type == float:
            values_dict[arg] = float(values_dict[arg])
        else:
            pass

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Cast values to appropriate types
    for arg_name, arg_value in values_dict.items():
        arg_type = self.get_cli_arg_type(parser_name, arg_name)
        if arg_type is not None and arg_value is not None:
            try:
                values_dict[arg_name] = arg_type(arg_value)
            except ValueError:
                raise CLIParserException(
                    f'Invalid value for argument "{arg_name}": {arg_value}. Expected {arg_type.__name__}.')

    return values_dict

