def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_file = os.path.join(plugin_dir, 'plugin.spec')
    if not os.path.isfile(spec_file):
        raise FileNotFoundError(f"Plugin spec file not found in {plugin_dir}")

    spec = yaml.safe_load(open(spec_file))

    flatten_dict = {}
    for key, value in spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_key = key + '.' + subkey
                flatten_dict[flatten_key] = subvalue
        else:
            flatten_dict[key] = value

    return flatten_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        with open(os.path.join(plugin_dir, 'plugin.spec'), 'r') as f:
            spec = yaml.safe_load(f)
    except FileNotFoundError:
        raise ValueError(f'Plugin spec file not found in {plugin_dir}')
    except yaml.YAMLError:
        raise ValueError(f'Invalid plugin spec file in {plugin_dir}')

    flatten_spec = {'name': spec.get('name'), 'version': spec.get('version')}
    for key, value in spec.get('properties').items():
        if isinstance(value, dict):
            if 'type' in value and value['type'] == 'list':
                flatten_spec[key] = '[]'
            else:
                flatten_spec[key] = value.get('default')
        else:
            flatten_spec[key] = value

    return flatten_spec

